// Regenerates features/machines/data/machines.js and features/machines/REVIEW.md
// from the machine database CSV.
//   node scripts/build-machine-db.mjs          → write both files
//   node scripts/build-machine-db.mjs --check  → fail if either is out of date
// The CSV in features/machines/data/ is the source of truth; never edit the
// generated files by hand. Exercises, muscles and flags are derived from the
// rows at load time (features/machines/services), so REVIEW.md reflects the
// current rules as well as the data.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { SOURCE_FILE, COLUMNS, parseMachineCsv } from '../features/machines/services/source.js';
import { createMachineDb, UNLISTED, UNRECORDED } from '../features/machines/services/db.js';
import { ATOMS } from '../features/machines/services/actions.js';
import { MUSCLE_ACTIONS } from '../features/muscles/data/muscleActions.js';

const DIR = 'features/machines';
const CSV = `${DIR}/data/${SOURCE_FILE}`;
const OUT = `${DIR}/data/machines.js`;
const REVIEW = `${DIR}/REVIEW.md`;

export function buildModule(csvBytes) {
  const rows = parseMachineCsv(csvBytes.toString('utf8'));
  const meta = {
    source: SOURCE_FILE,
    sha256: createHash('sha256').update(csvBytes).digest('hex'),
    columns: COLUMNS,
    rowCount: rows.length,
  };
  return `// GENERATED by scripts/build-machine-db.mjs from ${SOURCE_FILE} — do not edit.
// One array per machine, values exactly as in the file, in file order
// (array index + 2 = row number in the CSV). Columns: ${COLUMNS.join(', ')}.
// Exercises, muscles and review flags are derived when loaded (features/machines/services).

export const MACHINE_DB_META = ${JSON.stringify(meta, null, 2)};

export const MACHINE_ROWS = [
${rows.map((r) => JSON.stringify(r)).join(',\n')}
];
`;
}

const ident = (m) => `${m.brand} · ${m.line} · ${m.name}${m.model ? ` (${m.model})` : ''} — row ${m.row}`;
const md = (s) => String(s).replace(/\|/g, '\\|');

export function buildReview(csvBytes) {
  const rows = parseMachineCsv(csvBytes.toString('utf8'));
  const db = createMachineDb(rows, MUSCLE_ACTIONS);
  const ms = db.machines;
  const sha = createHash('sha256').update(csvBytes).digest('hex');
  const opts = db.options();
  const L = [];
  const p = (...a) => L.push(...a);

  p('# Machine database — review report', '',
    `Generated by \`scripts/build-machine-db.mjs\` from \`${SOURCE_FILE}\` (SHA-256 \`${sha.slice(0, 16)}…\`). Do not edit; regenerate.`,
    'Everything below is derived by the rules in `features/machines/services` — see README.md for them.', '');

  p('## Import', '',
    `- Rows in the file: **${rows.length}**. Machines imported: **${ms.length}**. Ids unique: **${new Set(ms.map((m) => m.id)).size === ms.length ? 'yes' : 'NO'}**.`,
    `- Exact duplicate rows: **${rows.length - new Set(rows.map((r) => r.join('\u0001'))).size}**. Rows sharing brand + line + machine + model: **${rows.length - new Set(rows.map((r) => r.slice(0, 4).join('\u0001'))).size}**.`,
    `- Brands: ${opts.brands.map((b) => `${b.name} ${b.count}`).join(', ')}.`, '');

  const matched = ms.filter((m) => m.exercises.some((e) => e.basis === 'name' || e.basis === 'action'));
  p('## Exercises', '',
    `- Matched to an exercise by their recorded action and name: **${matched.length}**.`,
    ...opts.stations.map((s) => `- ${s.name}s (no recorded action; offered for exercises done on that equipment): **${s.count}**.`),
    `- Unmatched (no recorded action, and the name doesn't identify an exercise): **${opts.unmatched}**.`, '',
    '| Exercise | Machines |', '|---|---|',
    ...opts.exercises.map((e) => `| ${md(e.name)} | ${e.count} |`), '');

  const confirmed = ms.filter((m) => m.modes.some((x) => x.targets.length));
  p('## Muscles', '',
    `- Machines with at least one target derived from their recorded action: **${confirmed.length}** of ${ms.length}.`,
    `- Machines with no recorded action (no muscles derived): **${ms.filter((m) => !m.recorded).length}**.`, '');
  const unresolved = new Map();
  for (const m of ms) for (const x of m.modes) for (const c of x.candidates) {
    const k = `${ATOMS[c.atom]}|${c.kind}`;
    if (!unresolved.has(k)) unresolved.set(k, { atom: ATOMS[c.atom], kind: c.kind, regions: new Set(), machines: new Set(), reason: c.reason });
    const u = unresolved.get(k); u.regions.add(c.entry.muscle); u.machines.add(m.id);
  }
  p('### Regions not recorded', '',
    'These actions match regions of your muscle list only with a qualifier the machine records don\'t state, so the region is left unresolved (shown as "region not recorded", never counted as a target).', '',
    '| Action | Kind | Machines | Possible regions |', '|---|---|---|---|',
    ...[...unresolved.values()].sort((a, b) => b.machines.size - a.machines.size)
      .map((u) => `| ${md(u.atom)} | ${u.kind} | ${u.machines.size} | ${md([...u.regions].join('; '))} |`), '');
  const unlisted = new Map();
  for (const m of ms) for (const x of m.modes) for (const a of x.unmapped) unlisted.set(ATOMS[a], (unlisted.get(ATOMS[a]) || new Set()).add(m.id));
  p('### Actions not in your muscle list', '',
    '| Action | Machines |', '|---|---|',
    ...[...unlisted].sort((a, b) => b[1].size - a[1].size).map(([a, s]) => `| ${md(a)} | ${s.size} |`), '');
  p('### Muscle groups (filter counts)', '', '| Group | Machines |', '|---|---|',
    ...opts.groups.map((g) => `| ${md(g.name)} | ${g.count} |`), '');

  const order = ['name-action-mismatch', 'mode-not-in-name', 'name-mentions-unrecorded', 'matched-by-action', 'unmatched',
    'shared-model', 'shared-name', 'no-model', 'no-source', 'profile-setting', 'multi-station', 'plane-depends-on-grip', 'depends-on-setup'];
  const titles = {
    'name-action-mismatch': 'Name and recorded action disagree',
    'mode-not-in-name': 'Recorded mode the name doesn\'t mention',
    'name-mentions-unrecorded': 'Name mentions a movement the action doesn\'t record',
    'matched-by-action': 'Exercise matched by action only',
    unmatched: 'Unmatched machines',
    'shared-model': 'Model code shared by several rows',
    'shared-name': 'Name shared by several rows',
    'no-model': 'No model code',
    'no-source': 'No profile source',
    'profile-setting': 'Profile depends on a setting',
    'multi-station': 'Multi-stations',
    'plane-depends-on-grip': 'Plane depends on grip (as recorded)',
    'depends-on-setup': 'Shoulder contribution depends on setup (as recorded)',
  };
  p('## Flags for review', '');
  for (const code of order) {
    const hits = ms.filter((m) => m.flags.some((f) => f.code === code));
    if (!hits.length) continue;
    p(`### ${titles[code]} (${hits.length})`, '');
    const many = hits.length > 40;
    if (many) p(`${hits[0].flags.find((f) => f.code === code).text}`, '', `Machines: ${hits.map((m) => `${m.brand} ${m.name}`).join('; ')}.`, '');
    else for (const m of hits) p(`- ${md(ident(m))}: ${md(m.flags.find((f) => f.code === code).text)}`);
    if (!many) p('');
  }
  p(`_No-action rows: ${ms.filter((m) => !m.recorded).length} (${opts.stations.map((s) => `${s.count} ${s.name.toLowerCase()}`).join(', ')}, ${opts.unmatched} unmatched). "${UNLISTED}" and "${UNRECORDED}" are filter groups, not muscles._`, '');
  return L.join('\n');
}

const isMain = process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/').split('/').pop());
if (isMain) {
  const bytes = readFileSync(CSV);
  const outputs = [[OUT, buildModule(bytes)], [REVIEW, buildReview(bytes)]];
  if (process.argv.includes('--check')) {
    let stale = false;
    for (const [file, next] of outputs) {
      let cur = '';
      try { cur = readFileSync(file, 'utf8'); } catch { /* missing */ }
      if (cur !== next) { console.error(`${file} is out of date — run node scripts/build-machine-db.mjs`); stale = true; }
    }
    if (stale) process.exit(1);
    console.log(`${OUT} and ${REVIEW} match ${CSV}`);
  } else {
    for (const [file, next] of outputs) { writeFileSync(file, next); console.log(`wrote ${file}`); }
  }
}
